tool_trace.output:
nfig in connection_map.values():
                history.extend(history_store.load_for_connection(config.name))
            history.sort(key=lambda entry: entry.timestamp, reverse=True)

        unsaved_store = getattr(self, "_unsaved_history_store", None)
        if unsaved_store is not None and hasattr(unsaved_store, "load_all"):
            history.extend(unsaved_store.load_all())

        if available_connections:
            history = [
                entry for entry in history
                if getattr(entry, "connection_name", None) in available_connections
            ]
        history.sort(key=lambda entry: entry.timestamp, reverse=True)
        connection_labels = {
            name: self._format_telescope_connection_label(config)
            for name, config in connection_map.items()
        }
        starred_by_connection = self._load_starred_by_connection(connection_map)
        self._telescope_auto_filter = auto_open_filter

        self.push_screen(
            QueryHistoryScreen(
                history,
                "All Servers",
                None,
                multi_connection=True,
                connection_labels=connection_labels,
                starred_by_connection=starred_by_connection,
                auto_open_filter=auto_open_filter,
            ),
            self._handle_telescope_result,
        )

    def _handle_telescope_result(self: QueryMixinHost, result: Any) -> None:
        """Handle the result from the telescope screen."""
        if result is None:
            return

        action, data = result
        if action == "select":
            query = data.get("query", "")
            connection_name = data.get("connection_name", "")
            database = data.get("database", "")
            self._run_telescope_query(connection_name, query, database=database)
        elif action == "delete":
            timestamp = data.get("timestamp", "")
            connection_name = data.get("connection_name", "")
            if timestamp and connection_name:
                self._get_history_store().delete_entry(connection_name, timestamp)
            if self._telescope_auto_filter:
                self.action_telescope_filter()
            else:
                self.action_telescope()
        elif action == "toggle_star":
            query = data.get("query", "")
            connection_name = data.get("connection_name", "")
            if query and connection_name:
                is_now_starred = self.services.starred_store.toggle_star(connection_name, query)
                if is_now_starred:
                    self.notify("Query starred")
                else:
                    self.notify("Query unstarred")
            if self._telescope_auto_filter:
                self.action_telescope_filter()
            else:
                self.action_telescope()

    def _run_telescope_query(
        self: QueryMixinHost, connection_name: str, query: str, *, database: str = ""
    ) -> None:
        if not query or not connection_name:
            return

        config = self._get_telescope_connection_map().get(connection_name)
        if config is None:
            self.notify(f"Connection '{connection_name}' not found", severity="warning")
            return

        # Resolve the active database from when the query was originally executed.
        # For old history entries without a database field, try to find one
        # from other entries for the same connection.
        if not database:
            database = self._infer_database_from_history(connection_name)

        self._apply_history_query(query)

        if (
            self.current_connection is not None
            and self.current_config is not None
            and self.current_config.name == connection_name
        ):
            if database:
                self._active_database = database
            self._pending_telescope_query = None
            return

        # Store database in the pending tuple so _maybe_run_pending_telescope_query
        # can restore it AFTER the connection callback resets _active_database.
        self._pending_telescope_query = (connection_name, query, database)
        self._connect_like_explorer(connection_name, config)

    def _get_telescope_connection_map(self: QueryMixinHost) -> dict[str, Any]:
        connection_map = {config.name: config for config in getattr(self, "connections", [])}
        for config in (
            getattr(self, "_direct_connection_config", None),
            getattr(self, "current_config", None),
        ):
            if config and config.name not in connection_map:
                connection_map[config.name] = config
        return connection_map

    def _connect_like_explorer(self: QueryMixinHost, connection_name: str, config: Any) -> None:
        node = None
        object_tree = getattr(self, "object_tree", None)
        if object_tree is not None:
            try:
                stack = [object_tree.root]
                while stack:
                    current = stack.pop()
                    for child in current.children:
                        if getattr(self, "_get_node_kind", None) and self._get_node_kind(child) != "connection":
                            stack.append(child)
                            continue
                        data = getattr(child, "data", None)
                        node_config = getattr(data, "config", None)
                        if node_config and node_config.name == connection_name:
                            node = child
                            stack = []
                            break
                        stack.append(child)
            except Exception:
                node = None

        if node is not None and hasattr(self, "_activate_tree_node"):
            self._activate_tree_node(node)
            return

        self.connect_to_server(config)

    def _infer_database_from_history(self: QueryMixinHost, connection_name: str) -> str:
        """Try to find the most recently used database for a connection from history."""
        try:
            history_store = self._get_history_store()
            entries = history_store.load_for_connection(connection_name)
            for entry in entries:
                db = getattr(entry, "database", "") or ""
                if db:
                    return db
        except Exception:
            pass
        return ""

    def _format_telescope_connection_label(self: QueryMixinHost, config: Any) -> str:
        endpoint = getattr(config, "tcp_endpoint", None)
        if endpoint is None:
            file_endpoint = getattr(config, "file_endpoint", None)
            if file_endpoint and getattr(file_endpoint, "path", ""):
                return file_endpoint.path
            return getattr(config, "name", "")
        database = getattr(config, "database", "")
        return database or getattr(config, "name", "")

    def _load_starred_by_connection(self: QueryMixinHost, connection_map: dict[str, Any]) -> dict[str, set[str]]:
        starred_store = self.services.starred_store
        loader = getattr(starred_store, "load_all", None)
        if callable(loader):
            return loader()
        return {
            name: starred_store.load_for_connection(name)
            for name in connection_map.keys()
        }

    def _delete_history_entry(self: QueryMixinHost, timestamp: str) -> None:
        """Delete a specific history entry by timestamp."""
        if not self.current_config:
            return
        self._get_history_store().delete_entry(self.current_config.name, timestamp)

    def _toggle_star(self: QueryMixinHost, query: str) -> None:
        """Toggle star status for a query."""
        if not self.current_config:
            return

        is_now_starred = self.services.starred_store.toggle_star(self.current_config.name, query)
        if is_now_starred:
            self.notify("Query starred")
        else:
            self.notify("Query unstarred")

"""PostgreSQL adapter using psycopg2."""

from __future__ import annotations

from typing import TYPE_CHECKING, Any

from sqlit.domains.connections.providers.postgresql.base import PostgresBaseAdapter
from sqlit.domains.connections.providers.registry import get_default_port
from sqlit.domains.connections.providers.tls import (
    TLS_MODE_DEFAULT,
    TLS_MODE_DISABLE,
    get_tls_files,
    get_tls_mode,
)

if TYPE_CHECKING:
    from sqlit.domains.connections.domain.config import ConnectionConfig


class PostgreSQLAdapter(PostgresBaseAdapter):
    """Adapter for PostgreSQL using psycopg2."""

    @property
    def name(self) -> str:
        return "PostgreSQL"

    @property
    def install_extra(self) -> str:
        return "postgres"

    @property
    def install_package(self) -> str:
        return "psycopg2-binary"

    @property
    def driver_import_names(self) -> tuple[str, ...]:
        return ("psycopg2",)

    def connect(self, config: ConnectionConfig) -> Any:
        """Connect to PostgreSQL database."""
        psycopg2 = self._import_driver_module(
            "psycopg2",
            driver_name=self.name,
            extra_name=self.install_extra,
            package_name=self.install_package,
        )

        endpoint = config.tcp_endpoint
        if endpoint is None:
            raise ValueError("PostgreSQL connections require a TCP-style endpoint.")
        connect_args: dict[str, Any] = {
            "connect_timeout": 10,
            "database": endpoint.database or "postgres",
        }
        host = endpoint.host
        # If the user only set a port (e.g. Postgres on a non-default port
        # like 5433), default the host to "localhost" — matches the Server
        # field's placeholder. Without this, libpq drops both args and
        # falls back to the default unix socket, ignoring the port.
        if not host and endpoint.port:
            host = "localhost"
        if host:
            connect_args["host"] = host
            connect_args["port"] = int(endpoint.port or get_default_port("postgresql"))
        if endpoint.username:
            connect_args["user"] = endpoint.username
        if endpoint.password is not None:
            connect_args["password"] = endpoint.password

        tls_mode = get_tls_mode(config)
        tls_ca, tls_cert, tls_key, tls_key_password = get_tls_files(config)
        if tls_mode != TLS_MODE_DEFAULT:
            connect_args["sslmode"] = tls_mode
        if tls_mode != TLS_MODE_DISABLE:
            if tls_ca:
                connect_args["sslrootcert"] = tls_ca
            if tls_cert:
                connect_args["sslcert"] = tls_cert
            if tls_key:
                connect_args["sslkey"] = tls_key
            if tls_key_password:
                connect_args["sslpassword"] = tls_key_password

        connect_args.update(config.extra_options)
        conn = psycopg2.connect(**connect_args)
        # Enable autocommit to avoid "transaction aborted" errors on failed statements
        conn.autocommit = True
        return conn

    def get_databases(self, conn: Any) -> list[str]:
        """Get list of databases from PostgreSQL."""
        cursor = conn.cursor()
        cursor.execute("SELECT datname FROM pg_database " "WHERE datistemplate = false ORDER BY datname")
        return [row[0] for row in cursor.fetchall()]

    def get_procedures(self, conn: Any, database: str | None = None) -> list[str]:
        """Get stored procedures/functions from PostgreSQL."""
        cursor = conn.cursor()
        cursor.execute(
            "SELECT routine_name FROM information_schema.routines "
            "WHERE routine_schema = 'public' AND routine_type = 'FUNCTION' "
            "ORDER BY routine_name"
        )
        return [row[0] for row in cursor.fetchall()]

"""Query alert classification and alert mode helpers."""

from __future__ import annotations

import re
from enum import IntEnum

from sqlit.domains.query.app.multi_statement import split_statements


class AlertMode(IntEnum):
    """Alert mode thresholds (user-configured)."""

    OFF = 0
    DELETE = 1
    WRITE = 2


class AlertSeverity(IntEnum):
    """Severity classification for a query."""

    NONE = 0
    WRITE = 1
    DELETE = 2


_DELETE_KEYWORDS = ("DELETE",)
_WRITE_KEYWORDS = (
    "CREATE",
    "ALTER",
    "DROP",
    "TRUNCATE",
    "RENAME",
    "INSERT",
    "UPDATE",
    "MERGE",
    "REPLACE",
    "UPSERT",
    "DELETE",
)

_DELETE_RE = re.compile(r"\b(?:%s)\b" % "|".join(_DELETE_KEYWORDS), re.IGNORECASE)
_WRITE_RE = re.compile(r"\b(?:%s)\b" % "|".join(_WRITE_KEYWORDS), re.IGNORECASE)

_SINGLE_QUOTE_RE = re.compile(r"'[^']*'")
_DOUBLE_QUOTE_RE = re.compile(r'"[^"]*"')
_BACKTICK_RE = re.compile(r"`[^`]*`")
_BRACKET_RE = re.compile(r"\[[^\]]*]")


def parse_alert_mode(value: str | int | None) -> AlertMode | None:
    """Parse a user-provided alert mode value."""
    if value is None:
        return None
    if isinstance(value, int):
        return _coerce_alert_mode(value)
    raw = str(value).strip().lower()
    if not raw:
        return None
    if raw in {"0", "off", "none", "disable", "disabled"}:
        return AlertMode.OFF
    if raw in {"1", "delete", "destructive", "danger"}:
        return AlertMode.DELETE
    if raw in {"2", "write", "writes", "edit", "update"}:
        return AlertMode.WRITE
    return None


def format_alert_mode(mode: AlertMode) -> str:
    """Human-readable alert mode."""
    if mode == AlertMode.DELETE:
        return "delete"
    if mode == AlertMode.WRITE:
        return "write"
    return "off"


def should_confirm(mode: AlertMode, severity: AlertSeverity) -> bool:
    """Return True if the given severity should prompt confirmation."""
    if mode == AlertMode.DELETE:
        return severity == AlertSeverity.DELETE
    if mode == AlertMode.WRITE:
        return severity in {AlertSeverity.WRITE, AlertSeverity.DELETE}
    return False


def classify_query_alert(sql: str) -> AlertSeverity:
    """Classify a SQL query for alerting."""
    if not sql:
        return AlertSeverity.NONE
    highest = AlertSeverity.NONE
    for statement in split_statements(sql):
        severity = _classify_statement(statement)
        if severity == AlertSeverity.DELETE:
            return severity
        if severity.value > highest.value:
            highest = severity
    return highest


def _classify_statement(statement: str) -> AlertSeverity:
    cleaned = _strip_comments_and_literals(statement)
    if not cleaned:
        return AlertSeverity.NONE
    if _DELETE_RE.search(cleaned):
        return AlertSeverity.DELETE
    if _WRITE_RE.search(cleaned):
        return AlertSeverity.WRITE
    return AlertSeverity.NONE


def _strip_comments_and_literals(sql: str) -> str:
    """Remove comments and quoted literals/identifiers for keyword scanning."""
    from sqlit.domains.query.editing.comments import strip_all_comments

    cleaned = strip_all_comments(sql)
    cleaned = _SINGLE_QUOTE_RE.sub("''", cleaned)
    cleaned = _DOUBLE_QUOTE_RE.sub('""', cleaned)
    cleaned = _BACKTICK_RE.sub("``", cleaned)
    cleaned = _BRACKET_RE.sub("[]", cleaned)
    return cleaned


def _coerce_alert_mode(value: int) -> AlertMode | None:
    try:
        mode = AlertMode(int(value))
    except (TypeError, ValueError):
        return None
    if mode in {AlertMode.OFF, AlertMode.DELETE, AlertMode.WRITE}:
        return mode
    return None

